<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\JobOffer;use App\Services\CandidateProfileResolver;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class CandidateFavoriteController extends Controller{public function index(Request $r):JsonResponse{$p=CandidateProfileResolver::resolve($r->user());return response()->json($p->favoriteOffers()->where('status','published')->latest('job_offer_favorites.created_at')->paginate(min(100,max(1,$r->integer('per_page',20)))));}public function store(Request $r,JobOffer $offer):JsonResponse{abort_unless($offer->status==='published',404);$p=CandidateProfileResolver::resolve($r->user());$p->favoriteOffers()->syncWithoutDetaching([$offer->id]);return response()->json(['favorited'=>true],201);}public function destroy(Request $r,JobOffer $offer):JsonResponse{$p=CandidateProfileResolver::resolve($r->user());$p->favoriteOffers()->detach($offer->id);return response()->json([],204);}}
